ExplanationDescriptionTerraform moduleTerragrunt configs <p>This module outlines the security groups required for this project - these act as the firewall for resources, controlling the traffic allowed to reach and leave the resources it is associated with.</p> <p>One key decision here was to provide minimal permissions required for each relevant resource to talk to the next in the traffic flow. This minimises exposure and vulnerability of the infrastructure - improving security posture.</p> <p>One issue I resolved however was circular dependecies when assigning minimal IAM permission:</p> <p>The egress of one resource references the security group of the downstream resource.</p> <p>The ingress of a downstream resource references the security group of the upstream resource.</p> <p>When they are defined as part of the security group at creation terraform cannot resolve the circular dependency and therefore fails to create the resources.</p> <p>The solution was to create blank security groups first and then add in the rules after.</p> <p>When adding in the rules, the blank security groups must be referenced using <code>security_group_id</code> field and chaining is done via <code>[source_security_group_id]</code> field.</p> <p>For the S3 gateway endpoint, a seperate security group rule must be defined that targets the prefix list. A data block was defined earlier to import this - and referenced here.</p> <p>Link to code </p> infrastructure/modules/security-groups/main.tf<pre><code>resource "aws_security_group" "alb" {
  name        = "${var.project_name}-${var.environment}-alb-sg"
  vpc_id      = var.vpc_id

  tags = {
  Name = "${var.project_name}-${var.environment}-alb-sg"
  }
}

resource "aws_security_group" "ecs" {
  name   = "${var.project_name}-${var.environment}-ecs-sg"
  vpc_id = var.vpc_id

  tags = {
  Name = "${var.project_name}-${var.environment}-ecs-sg"
  }
}

resource "aws_security_group" "vpc_endpoints" {
  name   = "${var.project_name}-${var.environment}-vpc-endpoints-sg"
  vpc_id = var.vpc_id

    tags = {
    Name = "${var.project_name}-${var.environment}-vpc-endpoints-sg"
    }
  }

data "aws_prefix_list" "s3" {
  name = "com.amazonaws.${var.aws_region}.s3"
}

# Avoid cyclical dependencies by defining rules separately
# https://developer.hashicorp.com/terraform/tutorials/state/troubleshooting-workflow#correct-a-cycle-error

resource "aws_security_group_rule" "alb_ingress_http" {
    type        = "ingress"
    description = "HTTP"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # From anywhere
    security_group_id = aws_security_group.alb.id
  }

resource "aws_security_group_rule" "alb_ingress_https" {
    type        = "ingress"
    description = "HTTPS"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # From anywhere
    security_group_id = aws_security_group.alb.id
  }

resource "aws_security_group_rule" "alb_egress" {
    type = "egress"
    from_port   = var.container_port
    to_port     = var.container_port
    protocol    = "tcp"           # ONLY to ECS on container port (8080)
    source_security_group_id = aws_security_group.ecs.id
    security_group_id = aws_security_group.alb.id
  }

resource "aws_security_group_rule" "ecs_ingress" {
    type            = "ingress"
    description     = "From ALB"
    from_port       = var.container_port
    to_port         = var.container_port
    protocol        = "tcp"
    source_security_group_id = aws_security_group.alb.id  # ONLY from ALB on same port (8080)
    security_group_id = aws_security_group.ecs.id
  }

resource "aws_security_group_rule" "ecs_egress" {
    type = "egress"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    source_security_group_id = aws_security_group.vpc_endpoints.id # VPC endpoints for ECS must allow HTTPS (port 443)
    security_group_id = aws_security_group.ecs.id
    description = "Allow all outbound traffic"
  }

resource "aws_security_group_rule" "vpc_endpoints_ingress" {
    type = "ingress"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    source_security_group_id = aws_security_group.ecs.id
    security_group_id = aws_security_group.vpc_endpoints.id
    description = "HTTPS from VPC"
  }

# For locking down access - S3 gateway endpoint needs to be specified too or ContainerPullError - access via prefix list:
# https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/security_group_rule#usage-with-prefix-list-ids

resource "aws_security_group_rule" "s3_gateway_egress" {
  type              = "egress"  
  from_port         = 443
  to_port           = 443  
  protocol          = "tcp"
  prefix_list_ids   = [data.aws_prefix_list.s3.id]
  security_group_id = aws_security_group.ecs.id  
  description       = "ECS S3 Gateway Egress"
}
</code></pre> <p>dev/security-groups/terragrunt.hcl<pre><code>include "root" {
