  depends_on = [cloudflare_dns_record.cert_validation]

  timeouts {
    create = "10m"  # Timeout to wait for DNS propogation
  }
}
</code></pre> infrastructure/modules/acm/main.tf<pre><code>resource "aws_acm_certificate" "main" {
