ExplanationDescriptionTerraform moduleTerragrunt configs <p>This module sets up the Application Load Balancer (ALB) - a single point of contact which forwards requests to the registered, healthy targets (EC2 instances) within the defined target group - distributing incoming traffic across multiple availability zones.</p> <p>It is configured with listeners on HTTPS and HTTP - with the following rules set up for incoming traffic from clients:</p> <p>If HTTPS, it will terminate the SSL/TLS connection using the issued ACM certificate (in the DNS module).</p> <p>If HTTP, the ALB will give a HTTP_301 permanently moved status code, and redirect the HTTP connection to HTTPs.</p> <p>It uses a round-robin algorithm to route traffic.</p> <p>It also has a health check - which checks if containers are healthy on the <code>/healthz</code> path before deciding to forward traffic across.</p> infrastructure/modules/alb/main.tf<pre><code>resource "aws_lb" "main" {
  name               = "${var.project_name}-${var.environment}-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [var.alb_security_group_id]
  subnets            = var.public_subnet_ids

  tags = {
    Name = "${var.project_name}-${var.environment}-alb"
  }
}

resource "aws_lb_target_group" "main" {
  name        = "${var.project_name}-${var.environment}-tg"
  port        = var.container_port
  protocol    = "HTTP"
  vpc_id      = var.vpc_id
  target_type = "ip"

  health_check {
    enabled             = true
    path                = "/healthz"
    port                = var.container_port
    protocol            = "HTTP"
    healthy_threshold   = 2         # # of successful checks till target healthy
    unhealthy_threshold = 3         # # of failed checks till target unhealthy
    timeout             = 5         # # of seconds until no response means failed health check
    interval            = 30        # # of seconds between health checks
    matcher             = "200"     # HTTP status code for checking health
  }

  tags = {
    Name = "${var.project_name}-${var.environment}-tg"
  }
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  certificate_arn   = var.certificate_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"
    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}
